// ──────────────────────────────────────────────
// Results Bar Chart (amCharts 5)
// ──────────────────────────────────────────────
let resultsRoot = null;

function buildResultsChart(taskKey) {
    // Static figures replaced the interactive results chart; no-op if the
    // amCharts container is not present.
    if (!document.getElementById("results-chart")) return;
    // Dispose previous chart
    if (resultsRoot) {
        resultsRoot.dispose();
    }
    resultsRoot = am5.Root.new("results-chart");
    resultsRoot.setThemes([am5themes_Animated.new(resultsRoot)]);

    const chart = resultsRoot.container.children.push(
        am5xy.XYChart.new(resultsRoot, {
            panX: false, panY: false,
            wheelX: "none", wheelY: "none",
            layout: resultsRoot.verticalLayout,
            paddingLeft: 0,
        })
    );

    const data = RESULTS_DATA[taskKey];
    if (!data) return;

    // Map encoder names for better display
    const formatEncoderName = (enc, condition) => {
        if (condition === 'concat') return 'Concat (All)';
        if (condition === 'shared') return 'Shared Space (All)';
        
        const nameMap = {
            'conch_v1': 'CONCH v1',
            'uni_v2': 'UNI v2',
            'ctranspath': 'CTransPath',
            'gigapath': 'GigaPath',
            'resnet50': 'ResNet50',
            'virchow2': 'Virchow 2',
            'virchow2_local': 'Virchow 2 Local',
            'owkin': 'Owkin',
            'phikon': 'Phikon',
            'phikon_v2': 'Phikon v2',
            'h-opt-125m': 'H-Opt',
            'ibot': 'iBOT',
            'lunit': 'Lunit',
            'plip': 'PLIP',
            'kaiko': 'Kaiko',
            'rudolf_v': 'RudolfV',
            'chf': 'CHF',
            'uni_v1': 'UNI v1'
        };
        return nameMap[enc] || enc;
    };

    const grouped = {};
    data.forEach(d => {
        const displayName = formatEncoderName(d.encoder, d.condition);
        if (!grouped[displayName]) grouped[displayName] = { is_joint: d.condition !== 'single' };
        grouped[displayName][d.mil] = d.auc;
    });

    const chartData = Object.keys(grouped).map(enc => ({
        encoder: enc,
        abmil: grouped[enc]['abmil'] || 0,
        transmil: grouped[enc]['transmil'] || 0,
        is_joint: grouped[enc].is_joint
    }));

    // Sort by best AUC descending, but keep joint methods at the end
    chartData.sort((a, b) => {
        if (a.is_joint && !b.is_joint) return 1;
        if (!a.is_joint && b.is_joint) return -1;
        return Math.max(b.abmil, b.transmil) - Math.max(a.abmil, a.transmil);
    });

    // X-axis (category)
    const xAxis = chart.xAxes.push(
        am5xy.CategoryAxis.new(resultsRoot, {
            categoryField: "encoder",
            renderer: am5xy.AxisRendererX.new(resultsRoot, {
                minGridDistance: 30,
                cellStartLocation: 0.1,
                cellEndLocation: 0.9,
            }),
            tooltip: am5.Tooltip.new(resultsRoot, {})
        })
    );
    xAxis.get("renderer").labels.template.setAll({
        fontSize: 12, rotation: -35, centerY: am5.p50, centerX: am5.p100,
        paddingRight: 10,
    });
    xAxis.data.setAll(chartData);

    // Y-axis (value)
    const yAxis = chart.yAxes.push(
        am5xy.ValueAxis.new(resultsRoot, {
            min: 0, max: 1,
            renderer: am5xy.AxisRendererY.new(resultsRoot, {}),
            numberFormat: "#.##",
        })
    );
    yAxis.children.unshift(am5.Label.new(resultsRoot, {
        text: "AUROC",
        rotation: -90,
        y: am5.p50,
        centerX: am5.p50,
        fontSize: 13,
        fontWeight: "600",
    }));

    // ABMIL series
    const abmilSeries = chart.series.push(
        am5xy.ColumnSeries.new(resultsRoot, {
            name: "ABMIL",
            xAxis: xAxis, yAxis: yAxis,
            valueYField: "abmil",
            categoryXField: "encoder",
            tooltip: am5.Tooltip.new(resultsRoot, {
                labelText: "{categoryX} (ABMIL)\nAUROC: {valueY.formatNumber('#.####')}"
            })
        })
    );
    abmilSeries.columns.template.setAll({
        cornerRadiusTL: 4, cornerRadiusTR: 4,
        strokeOpacity: 0,
        fill: am5.color("#3b82f6"),
    });
    abmilSeries.data.setAll(chartData);

    // TransMIL series
    const transmilSeries = chart.series.push(
        am5xy.ColumnSeries.new(resultsRoot, {
            name: "TransMIL",
            xAxis: xAxis, yAxis: yAxis,
            valueYField: "transmil",
            categoryXField: "encoder",
            tooltip: am5.Tooltip.new(resultsRoot, {
                labelText: "{categoryX} (TransMIL)\nAUROC: {valueY.formatNumber('#.####')}"
            })
        })
    );
    transmilSeries.columns.template.setAll({
        cornerRadiusTL: 4, cornerRadiusTR: 4,
        strokeOpacity: 0,
        fill: am5.color("#8b5cf6"),
    });
    transmilSeries.data.setAll(chartData);

    // Animate on load
    chart.appear(1000, 100);
}

function switchResultsTask(btn, taskKey) {
    document.querySelectorAll('#results .results-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    buildResultsChart(taskKey);
}

// ──────────────────────────────────────────────
// Similarity Heatmap (amCharts 5)
// ──────────────────────────────────────────────
let metricsRoot = null;

function buildHeatmap(metricKey) {
    // Static figures replaced the interactive similarity heatmap; no-op if the
    // amCharts container is not present.
    if (!document.getElementById("metrics-chart")) return;
    if (metricsRoot) {
        metricsRoot.dispose();
    }
    metricsRoot = am5.Root.new("metrics-chart");
    metricsRoot.setThemes([am5themes_Animated.new(metricsRoot)]);

    const chart = metricsRoot.container.children.push(
        am5xy.XYChart.new(metricsRoot, {
            panX: false, panY: false,
            wheelX: "none", wheelY: "none",
            layout: metricsRoot.verticalLayout,
        })
    );

    const metricInfo = METRICS_DATA[metricKey];
    if (!metricInfo) return;

    const encoders = metricInfo.encoders;
    const heatData = metricInfo.data;

    const ENCODER_NAMES = {
        "chief": "CHIEF",
        "feather": "Feather",
        "gigapath": "GigaPath-slide",
        "madeleine": "Madeleine",
        "prism": "PRISM",
        "titan": "TITAN"
    };

    // Filter for lower triangle and map names
    const filteredData = heatData.filter(item => {
        const rowIdx = encoders.indexOf(item.y);
        const colIdx = encoders.indexOf(item.x);
        return rowIdx >= colIdx;
    }).map(item => ({
        x: ENCODER_NAMES[item.x] || item.x,
        y: ENCODER_NAMES[item.y] || item.y,
        value: item.value
    }));

    // X-axis
    const xAxis = chart.xAxes.push(
        am5xy.CategoryAxis.new(metricsRoot, {
            categoryField: "x",
            renderer: am5xy.AxisRendererX.new(metricsRoot, {
                minGridDistance: 40,
            }),
        })
    );
    xAxis.get("renderer").labels.template.setAll({
        fontSize: 13, fontWeight: "600",
        rotation: -45, centerY: am5.p50, centerX: am5.p100,
        paddingRight: 10, paddingBottom: 15
    });
    xAxis.data.setAll(encoders.map(e => ({ x: ENCODER_NAMES[e] || e })));

    // Y-axis
    const yAxis = chart.yAxes.push(
        am5xy.CategoryAxis.new(metricsRoot, {
            categoryField: "y",
            renderer: am5xy.AxisRendererY.new(metricsRoot, {
                minGridDistance: 40,
                inversed: true,
            }),
        })
    );
    yAxis.get("renderer").labels.template.setAll({
        fontSize: 13, fontWeight: "600",
        paddingRight: 15
    });
    yAxis.data.setAll(encoders.map(e => ({ y: ENCODER_NAMES[e] || e })));

    // Heatmap series
    const series = chart.series.push(
        am5xy.ColumnSeries.new(metricsRoot, {
            xAxis: xAxis,
            yAxis: yAxis,
            categoryXField: "x",
            categoryYField: "y",
            valueField: "value",
            calculateAggregates: true,
            tooltip: am5.Tooltip.new(metricsRoot, {
                labelText: "{categoryX} vs {categoryY}\n{value.formatNumber('#.####')}"
            })
        })
    );

    series.columns.template.setAll({
        strokeOpacity: 1,
        stroke: am5.color("#ffffff"),
        strokeWidth: 2,
        cornerRadiusTL: 4, cornerRadiusTR: 4,
        cornerRadiusBL: 4, cornerRadiusBR: 4,
        tooltipText: "{categoryX} vs {categoryY}\n{value.formatNumber('#.####')}",
        width: am5.percent(100),
        height: am5.percent(100),
    });

    // Premium Color gradient from very light blue/slate (low) to deep purple (high)
    series.set("heatRules", [{
        target: series.columns.template,
        min: am5.color("#f8fafc"),
        max: am5.color("#5b21b6"),
        dataField: "value",
        key: "fill",
    }]);

    series.data.setAll(filteredData);

    let minVal = Math.min(...filteredData.map(d => d.value));
    let maxVal = Math.max(...filteredData.map(d => d.value));

    // Heat legend
    const heatLegend = chart.bottomAxesContainer.children.push(
        am5.HeatLegend.new(metricsRoot, {
            orientation: "horizontal",
            startColor: am5.color("#f8fafc"),
            endColor: am5.color("#5b21b6"),
            startValue: minVal,
            endValue: maxVal,
            startText: minVal.toFixed(2),
            endText: maxVal.toFixed(2),
            stepCount: 5,
            paddingTop: 20,
            paddingBottom: 20
        })
    );

    chart.appear(1000, 100);
}

function switchMetric(btn, metricKey) {
    document.querySelectorAll('#metrics .results-tab').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    buildHeatmap(metricKey);
}

// ──────────────────────────────────────────────
// Initialize on page load
// ──────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', function() {
    // Build default charts
    buildResultsChart('tcga_brca_subtype');
    buildHeatmap('linear_cka');

    // Scroll animations (IntersectionObserver)
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('visible');
            }
        });
    }, { threshold: 0.1 });

    document.querySelectorAll('.animate-up').forEach(el => observer.observe(el));

    // Scroll Progress Bar
    const progressBar = document.getElementById('scroll-progress');
    window.addEventListener('scroll', () => {
        const scrollTop = window.scrollY || document.documentElement.scrollTop;
        const scrollHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        const scrollPercent = (scrollTop / scrollHeight) * 100;
        if (progressBar) {
            progressBar.style.width = scrollPercent + '%';
        }
    });
});

